target.css:
:root {
  --clay: #c1440e;
  --clay-light: #f5e6de;
  --clay-mid: #e8a882;
  --earth: #5c3d2e;
  --earth-light: #8b6351;
  --cream: #fdf6f0;
  --ash: #f0ebe6;
  --text-dark: #2e1a10;
  --text-mid: #6b4c3b;
  --text-light: #a07060;
  --badge-bg: #fff3ee;
  --badge-border: #e8c4b0;
  --divider: #ead8cd;
  --avatar-bg: #c1440e;
  --avatar-text: #ffffff;
  --include-bg: #fdf6f0;
  --include-border: #e8d4c8;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.card {
  width: 480px;
  background-color: var(--cream);
  border-radius: 16px;
  border: 2px solid var(--clay-mid);
  overflow: hidden;
}

.card-header {
  background-color: var(--clay);
  padding: 14px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.studio-label {
  color: var(--avatar-text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.session-badge {
  background-color: var(--badge-bg);
  color: var(--clay);
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 20px;
  border: 1px solid var(--badge-border);
}

.card-body {
  padding: 18px 20px;
}

.workshop-title {
  font-size: 22px;
  font-weight: 700;
  color: var(--text-dark);
  margin-bottom: 10px;
  line-height: 1.2;
}

.workshop-meta {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.meta-item {
  font-size: 13px;
  color: var(--text-mid);
  font-weight: 500;
}

.divider {
  height: 1px;
  background-color: var(--divider);
  margin: 14px 0;
}

.includes-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

.include-item {
  background-color: var(--include-bg);
  border: 1px solid var(--include-border);
  border-radius: 10px;
  padding: 10px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}

.include-icon {
  font-size: 20px;
  line-height: 1;
}

.include-text {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-mid);
  text-align: center;
  line-height: 1.3;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.instructor {
  display: flex;
  align-items: center;
  gap: 10px;
}

.instructor-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: var(--avatar-bg);
  color: var(--avatar-text);
  font-size: 13px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

.instructor-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-dark);
}

.instructor-role {
  font-size: 12px;
  color: var(--text-light);
  font-weight: 400;
}

.price-block {
  text-align: right;
}

.price-amount {
  font-size: 28px;
  font-weight: 800;
  color: var(--clay);
  line-height: 1;
}

.price-label {
  font-size: 12px;
  color: var(--text-light);
  font-weight: 400;
  margin-top: 2px;
}

